 ;WITH ranked AS (
 SELECT *,ROW_NUMBER() OVER(PARTITION BY cst_id ORDER BY cst_create_date DESC,
  CONVERT(varbinary(100),cst_key) DESC, CONVERT(varbinary(100),cst_firstname) DESC,
