  OR sls_order_dt>sls_ship_dt OR sls_order_dt>sls_due_dt OR sls_ship_dt>sls_due_dt
  OR sls_order_dt>CONVERT(date,@load_time) OR sls_ship_dt>CONVERT(date,@load_time) OR sls_due_dt>CONVERT(date,@load_time))
