IF @execute_refresh=1 AND EXISTS(SELECT 1 FROM silver.crm_prd_info WHERE dwh_create_date IS NULL OR dwh_create_date<>@load_time) THROW 51314,'Inconsistent full-refresh timestamp.',1;
IF (SELECT COUNT_BIG(*) FROM silver.crm_sales_details)<>(SELECT expected_rows FROM @targets WHERE table_name='crm_sales_details') THROW 51391,'Critical snapshot row-count validation failed.',1;
IF @execute_refresh=1 AND EXISTS(SELECT 1 FROM silver.crm_sales_details WHERE dwh_create_date IS NULL OR dwh_create_date<>@load_time) THROW 51314,'Inconsistent full-refresh timestamp.',1;
IF (SELECT COUNT_BIG(*) FROM silver.erp_cust_az12)<>(SELECT expected_rows FROM @targets WHERE table_name='erp_cust_az12') THROW 51391,'Critical snapshot row-count validation failed.',1;
IF @execute_refresh=1 AND EXISTS(SELECT 1 FROM silver.erp_cust_az12 WHERE dwh_create_date IS NULL OR dwh_create_date<>@load_time) THROW 51314,'Inconsistent full-refresh timestamp.',1;
IF (SELECT COUNT_BIG(*) FROM silver.erp_loc_a101)<>(SELECT expected_rows FROM @targets WHERE table_name='erp_loc_a101') THROW 51391,'Critical snapshot row-count validation failed.',1;
IF @execute_refresh=1 AND EXISTS(SELECT 1 FROM silver.erp_loc_a101 WHERE dwh_create_date IS NULL OR dwh_create_date<>@load_time) THROW 51314,'Inconsistent full-refresh timestamp.',1;
IF (SELECT COUNT_BIG(*) FROM silver.erp_px_cat_g1v2)<>(SELECT expected_rows FROM @targets WHERE table_name='erp_px_cat_g1v2') THROW 51391,'Critical snapshot row-count validation failed.',1;
IF @execute_refresh=1 AND EXISTS(SELECT 1 FROM silver.erp_px_cat_g1v2 WHERE dwh_create_date IS NULL OR dwh_create_date<>@load_time) THROW 51314,'Inconsistent full-refresh timestamp.',1;

 COMMIT TRANSACTION;
 SELECT @run_id AS run_id,@execute_refresh AS refreshed,@load_time AS load_time,
  CASE WHEN @execute_refresh=1 THEN 'COMMITTED' ELSE 'PREVIEW PASSED: no Silver writes' END AS status;
 END TRY
 BEGIN CATCH
  IF XACT_STATE()<>0 ROLLBACK TRANSACTION;
  SELECT @run_id AS run_id,'ROLLED BACK / NOT COMMITTED' AS status,ERROR_NUMBER() AS error_number,
   ERROR_PROCEDURE() AS error_procedure,ERROR_LINE() AS error_line,ERROR_MESSAGE() AS error_message;
  THROW;
 END CATCH;
END;
GO
